#!/usr/bin/env node

/**
 * Script to export environment variables from .env.test to documentation wiki
 */

const fs = require('fs');
const path = require('path');
const https = require('https');

// Read .env.test file
const envFilePath = path.join(__dirname, '.env.test');
const envContent = fs.readFileSync(envFilePath, 'utf8');

// Parse environment variables
const envVars = {};
const lines = envContent.split('\n');

for (const line of lines) {
  // Skip comments and empty lines
  if (line.trim() === '' || line.startsWith('#')) {
    continue;
  }

  const [key, ...valueParts] = line.split('=');
  if (key && valueParts.length > 0) {
    const value = valueParts.join('=');
    envVars[key.trim()] = value;
  }
}

// Prepare the payload for the API
const payload = {
  source: '.env.test',
  environment: 'test',
  timestamp: new Date().toISOString(),
  variables: envVars
};

console.log('Environment variables to be exported:');
console.log(JSON.stringify(payload, null, 2));

// POST request to the API endpoint
const postData = JSON.stringify(payload);

const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = https.request(options, (res) => {
  let responseData = '';

  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('\nResponse from server:');
    console.log(`Status: ${res.statusCode}`);
    console.log(`Body: ${responseData}`);
  });
});

req.on('error', (error) => {
  console.error('\nError making request:', error.message);
  process.exit(1);
});

req.write(postData);
req.end();

