#!/usr/bin/env node

/**
 * Export environment variables from .env.test
 * Post them to http://localhost:3003/api/doc-export
 */

const fs = require('fs');
const http = require('http');

// Read .env.test file
envFileContent = fs.readFileSync('.env.test', 'utf8');

// Parse environment variables
const envVars = {};
envFileContent.split('\n').forEach(line => {
    const trimmedLine = line.trim();
    // Skip empty lines and comments
    if (trimmedLine && !trimmedLine.startsWith('#')) {
        const [key, ...valueParts] = trimmedLine.split('=');
        const value = valueParts.join('='); // Preserve the full value in case it contains '='
        if (key && value) {
            envVars[key] = value;
        }
    }
});

console.log('Parsed environment variables:');
console.log(JSON.stringify(envVars, null, 2));

// Prepare request data
const postData = JSON.stringify(envVars);

// Options for POST request
const options = {
    hostname: 'localhost',
    port: 3003,
    path: '/api/doc-export',
    method: 'POST',
    headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
    }
};

// Make the request
const req = http.request(options, (res) => {
    let data = '';

    res.on('data', (chunk) => {
        data += chunk;
    });

    res.on('end', () => {
        if (res.statusCode === 200 || res.statusCode === 201) {
            console.log('\n✓ Successfully exported environment variables to wiki!');
            console.log('Response:', data);
        } else {
            console.error('\n✗ Failed to export environment variables');
            console.error('Status:', res.statusCode);
            console.error('Response:', data);
            process.exit(1);
        }
    });
});

req.on('error', (error) => {
    console.error('\n✗ Error making request to http://localhost:3003/api/doc-export');
    console.error('Error:', error.message);
    process.exit(1);
});

// Write data to request
req.write(postData);
req.end();

console.log('Sending environment variables to http://localhost:3003/api/doc-export...');
